* {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}
.imageSection {
  background-image: url(../../assets/images/theorySupportbanner.png);
  position: relative;
  width: 100%;
  padding: 10rem 0px;
  background-size: cover;
  background-position: center;
}
.maincontent {
  display: flex;
  max-width: 1640px;
  width: 100%;

  margin-left: auto;
  margin-right: auto;
  align-items: center;
}

.content {
  position: relative;
  width: 100%;
  color: white;
  text-align: left;
  padding: 1rem;
}

.heading1 h1 {
  color: #ffffff;
  font-size: 1.5rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 12px;
  font-family: "Segoe UI", Tahoma, Geneva, Verdana, sans-serif;
  padding-bottom: 0.8rem;
}
.heading2 h2 {
  color: #ffffff;
  font-size: 5rem;
  font-weight: 700;

  font-family: "Segoe UI", Tahoma, Geneva, Verdana, sans-serif;
  padding-top: 0.8rem;
  padding-bottom: 0.5rem;
  margin-bottom: 20px;
}
#btn {
  font-size: 14px;
  font-weight: 600;
  letter-spacing: 0px;
  border: 1px solid #7c7c7c;
  color: #ffffff;
  background: linear-gradient(135deg, #150071e8, #6574ffee);
  padding: 15px 60px 15px 60px;
  transition: color 0.3s, border-color 0.3s, transform 0.3s;
  border-radius: 6px; /* Added transform to transition */
}

#btn:hover {
  background: linear-gradient(135deg, #6574ffee, #150071e8);
  transform: scale(1.1); /* Grow size by 10% on hover */
  animation: bounce 0.3s infinite alternate; /* Applying bouncing animation */
}
.csrPagesLd {
  padding: 1rem;
  position: sticky;
  max-width: 1440px;
  margin-left: auto;
  margin-right: auto;
  width: 100%;
  background: linear-gradient(135deg, #00157199, #01764b76);
  border-radius: 6px;
  font-family: "Segoe UI", Tahoma, Geneva, Verdana, sans-serif;
    box-shadow: 0 0 20px rgba(54, 54, 54, 0.656);
}
.csrPagesLd p {
  color: white;
  font-size: 1.1rem;
  margin-bottom: 0px;
  text-align: left;
  font-family: "Segoe UI", Tahoma, Geneva, Verdana, sans-serif;
}
@keyframes bounce {
  0% {
    transform: scale(1); /* Original size */
  }
  100% {
    transform: scale(1.05); /* Slightly bigger size */
  }
}

.video {
  position: relative;

  max-width: 50%;
  width: 100%;
  text-align: center;
  padding: 150px 150px 150px 150px;
}
.playIcon {
  position: absolute;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);

  color: #fff; /* Adjust color and opacity as needed */
  font-size: 170px;
  filter: drop-shadow(1px 0 6px rgba(0, 0, 0, 0.3));
}

.video img {
  max-width: 100%;
  height: auto;
}
@media (max-width: 1020px) {
  .heading1 h1 {
    font-size: 1.2rem;
  }
  .heading2 h2 {
    font-size: 4.2rem;
  }
  .imageSection {
    padding: 8rem 0px;
  }
}
@media (max-width: 767px) {
  .imageSection {
