/* /////////////////////////why choose us css/////////// */
.features {
  padding: 2rem 0;
}
.features h4 {
  color: white;
  font-size: 65px;
  font-weight: 900;
  line-height: 1.2em;
  text-align: center;

  margin-bottom: 20px;
  max-width: 1000px;
  margin-left: auto;
  margin-right: auto;
}
.features p {
  color: white;
  line-height: 28px;
  text-align: center;
  font-weight: 400;

  max-width: 1200px;
  margin-left: auto;
  margin-right: auto;
}
.mainFeatures {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(250px, 1fr));
  gap: 20px;

  text-align: center;
  max-width: 1140px;
  padding-left: 15px;
  padding-right: 15px;
  padding-top: 2rem;
  margin-left: auto;
  margin-right: auto;
  width: 100%;
  position: relative;
}
.column {
  padding: 15px 15px 15px 15px;
  background-color: black;
  border-radius: 20px;
  border: 1px solid white;
  box-shadow: 0px 0px 55px 5px rgba(0, 0, 0, 0.06);

  transition: box-shadow 0.3s ease;
  opacity: 0;
  transform: translateY(100%);
  animation: slideUp 7s forwards;
}
.column:nth-child(1) h3 {
  color: red;
}
.column:nth-child(2) h3 {
  color: #fbc809;
}
.column:nth-child(3) h3 {
  color: #cb2c92;
}
.column:nth-child(4) h3 {
  color: #008081;
}
.column:nth-child(1) p {
  color: red;
}
.column:nth-child(2) p {
  color: #fbc809;
}
.column:nth-child(3) p {
  color: #cb2c92;
}
.column:nth-child(4) p {
  color: #008081;
}

.column:nth-child(1) {
  animation-delay: 0s;
}

.column:nth-child(2) {
  animation-delay: 1s;
}

.column:nth-child(3) {
  animation-delay: 2s;
}
.column:nth-child(4) {
  animation-delay: 3s;
}
.column:nth-child(1):hover {
  border: 1px solid #d60f20;
}
.column:nth-child(2):hover {
  border: 1px solid #d6d30f;
}
.column:nth-child(3):hover {
  border: 1px solid #d60fab;
}
.column:nth-child(4):hover {
  border: 1px solid #00c4a3;
}

@keyframes slideUp {
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

.column:hover {
  box-shadow: 0px 0px 55px 5px rgba(0, 0, 0, 0.203);
}
.column span {
  font-size: 50px;
  color: white;
  display: inline-block;
  padding: 15px;
  margin-right: auto;
  margin-left: auto;
}
.column img {
  max-width: 150px;
  width: 100%;
}
.column h3 {
  font-size: 26px;
  line-height: 1.2;
  font-weight: 700;
  margin-bottom: 10px;
  color: white;
}
.column p {
  font-size: 16px;

  font-weight: 300;
  line-height: 1.7em;
  color: white;
}
#featuresIcon {
  transition: transform 0.3s ease;
}
#featuresIcon:hover {
  transform: scale(1.2);
  color: #eb0009;
}
@media (max-width: 1085px) {
  .features h4 {
    font-size: 45px;
  }
}
@media (max-width: 767px) {
  .features h4 {
    font-size: 30px;
  }
}
