.christmasbanner {
  background: url(../../../assets/images/banner1.png);
  background-size: cover;
  background-position: left;

  height: 85vh;
  position: relative;
}

.christmasbannerheading {
  width: 50%;
  padding: 3rem 3rem;
}
#christmasheadings {
  max-width: 550px;
  height: 270px;
  width: 100%;
  padding: 3.2rem 2rem;
}
#holyhat {
  z-index: 3;
  max-width: 140px;
  top: 1px;
  left: 10px;
}
#holyplant {
  max-width: 140px;
  top: 10px;
  right: 5px;
}
#textchristmas {
  z-index: 2;
  font-size: 3.5rem;
  font-weight: 800;
  line-height: 48px;
}
.displayImg {
  display: none;
}

#logoImgBanner {
  margin-bottom: 2rem;
  max-width: 300px;
  width: 100%;
}
#logoImgBanner P {
  text-align: right;
  color: white;
  font-weight: 700;
}
.logoImgBanner {
  max-width: 300px;
  width: 100%;
}

/* /////////////////////////// */

#tokenImg {
  position: absolute;
  right: 100px;
  top: 10px;
}
#tokenImg2 {
  position: absolute;
  right: 250px;
  top: 10px;
}
#tokenImg3 {
  position: absolute;
  right: 400px;
  top: 10px;
}
.tokenImg {
  max-width: 140px;
  width: 100%;
}

@media (max-width: 1340px) {
  .christmasbanner {
    margin-top: 1.5rem;
  }
}

@media (max-width: 1167px) {
  .christmasbannerheading {
    padding: 3rem 0px 2rem 3rem;
  }
  #christmasheadings {
    padding: 3rem 0px;
  }

  #holyhat {
    z-index: 3;
    max-width: 140px;
    top: 10px;
    left: 0px;
  }
  #holyplant {
    max-width: 120px;
    top: 15px;
    right: 0px;
  }
  .tokenImg {
    max-width: 100px;
    width: 100%;
  }

  #tokenImg {
    position: absolute;
    right: 50px;
    top: 5px;
  }
  #tokenImg2 {
    position: absolute;
    right: 160px;
    top: 5px;
  }
  #tokenImg3 {
    position: absolute;
    right: 270px;
    top: 5px;
  }
}

@media (max-width: 1067px) {
  #textchristmas {
    z-index: 2;
    font-size: 3rem;
    font-weight: 800;
    line-height: 45px;
  }
  #holyhat {
    z-index: 3;
    max-width: 120px;
    top: 15px;
    left: 0px;
  }
  #holyplant {
    max-width: 100px;
    top: 20px;
    right: 0px;
  }
}

@media (max-width: 877px) {
  .christmasbannerheading {
    width: 60%;
  }

  #textchristmas {
    z-index: 2;
    font-size: 3rem;
    font-weight: 800;
    line-height: 45px;
  }
  #holyhat {
    z-index: 3;
    max-width: 100px;
    top: 25px;
    left: 20px;
  }
  #holyplant {
    max-width: 90px;
    top: 30px;
    right: 20px;
  }

  .tokenImg {
    max-width: 90px;
    width: 100%;
  }

  #tokenImg {
    position: absolute;
    right: 20px;
    top: 5px;
  }
  #tokenImg2 {
    position: absolute;
    right: 120px;
    top: 5px;
  }
  #tokenImg3 {
    position: absolute;
    right: 220px;
    top: 5px;
  }
}

@media (max-width: 787px) {

      #logoImgBanner {
    max-width: 200px;
    width: 100%;
    margin-bottom: 1rem;
  }
  .logoImgBanner {
    max-width: 200px;
    width: 100%;
  }

  
  .christmasbanner {
    margin-top: 0rem;
     background: url(../../../assets/images/tabbanner1.png);
     background-position: center;
     height: 75vh
  }
  .tokenImg {
    display: none;
  }

  .christmasbannerheading {
    padding: 3rem 2rem;
  }
  #christmasheadings {
    padding: 3rem 0px;
  }

  #christmasheadings {
    max-width: 100%;
    width: 100%;
    display: none;
  }
  .displayImg {
    text-align: center;
    display: block;
  }
  .displayImg img {
    max-width: 500px;
    width: 100%;
  }
  .christmasbannerheading {
    width: 100%;
  }

  #textchristmas {
    z-index: 2;
    font-size: 3.5rem;
    font-weight: 800;
    line-height: 48px;
  }
  #holyhat {
    z-index: 3;
    max-width: 100px;
    top: 18px;
    left: 110px;
  }
  #holyplant {
    max-width: 90px;
    top: 30px;
    right: 100px;
  }
}
@media (max-width: 467px) {
  .christmasbanner {

    margin-top: 0rem;
     background: url(../../../assets/images/mobilebanner1.png);
     background-position: center;
     height: 75vh
  
  }
  .displayImg img {
    max-width: 500px;
    width: 100%;
  }
  .christmasbannerheading {
    padding: 3rem 0.5rem 1.5rem 0.5rem;
  }
}
