/* src/components/ManualTransmission.module.css */

.transmissionContainer {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  margin-top: 20px;
  font-family: "Arial", sans-serif;
  background: linear-gradient(
    135deg,
    #ff7f50,
    #ff6347,
    #ffd700,
    #00ff7f,
    #1e90ff,
    #8a2be2
  );
  background-size: 600% 600%;
  animation: gradientAnimation 12s ease infinite;
  min-height: 70vh;
  padding: 20px;
  border-radius: 30px;
  max-width: 1640px;
  margin-right: auto;
  margin-left: auto;
}

@keyframes gradientAnimation {
  0% {
    background-position: 0% 50%;
  }
  50% {
    background-position: 100% 50%;
  }
  100% {
    background-position: 0% 50%;
  }
}

.gearBoxTitle {
  font-size: 2.5rem;
  margin-bottom: 20px;
  color: #fff;
  text-shadow: 2px 2px 5px rgba(0, 0, 0, 0.3);
}

.shifterContainer {
  display: flex;
  flex-direction: column;
  align-items: center;
}

.shifter {
  width: 100px;
  height: 100px;
  background: #ff0000;
  border-radius: 50%;
  position: relative;
  display: flex;
  align-items: center;
  justify-content: center;
  box-shadow: 0px 4px 8px rgba(0, 0, 0, 0.2);
}

.knob {
  width: 60px;
  height: 60px;
  background: #f1f1f1;
  border-radius: 50%;
  position: absolute;
  top: 10px;
  box-shadow: 0px 4px 8px rgba(0, 0, 0, 0.1);
}

.gearList {
  display: grid;
  grid-template-columns: repeat(3, 60px);
  gap: 20px;
  margin-top: 30px;
}

.gear {
  display: flex;
  justify-content: center;
  align-items: center;
  width: 60px;
  height: 60px;
  background-color: #c7c7c7;
  border-radius: 50%;
  cursor: pointer;
  font-size: 1.4rem;
  font-weight: bold;
  color: white;
  transition: transform 0.3s ease, background-color 0.3s ease;
  box-shadow: 0px 4px 6px rgba(0, 0, 0, 0.1);
}

.gear:hover {
  transform: translateY(-8px);
  background-color: #ff6347;
  color: white;
}

.active {
  transform: scale(1.2);
  background-color: #000000 !important;
  color: white !important;
}

.selectedGear {
  margin-top: 20px;
  font-size: 1.3rem;
  color: #fff;
  font-weight: bold;
  text-shadow: 1px 1px 4px rgba(0, 0, 0, 0.4);
}

.selectedGear-enter {
  opacity: 0;
}

.selectedGear-exit {
  opacity: 0;
}

.manualContent {
  max-width: 1200px;
  margin-right: auto;
  margin-left: auto;
  margin-top: 2rem;
  margin-bottom: 2rem;
  background: linear-gradient(135deg, #0017c8, #c100bb);
  border-radius: 20px;
}
.manualPara {
  background-color: rgba(255, 255, 255, 0.269);
  padding: 2rem 1rem;
  border-radius: 20px;
}
.manualPara p {
  color: white;
  font-size: 1.2rem;
  font-weight: 500;
}
