* {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}
.imageSection {
  position: relative;
  width: 100%;
  height: 570px;
  background-image: url("../../assets/images/Home-banner-img-1.jpg"); /* Add the path to your background image */
  background-size: cover;
  background-position: center;
}
.maincontent {
  display: flex;
  max-width: 1140px;
  width: 100%;
  height: 570px;
  margin-left: auto;
  margin-right: auto;
  align-items: center;
}
.overlay {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  background-color: rgba(0, 0, 0, 0.795); /* Adjust opacity here */
}

.content {
  position: relative;
  z-index: 1;
  max-width: 100%;
  width: 100%;
  color: white;
  text-align: center;
  padding: 0px 20px 0px 0px;
}

.heading1 h1 {
  color: #ffffff;
  font-size: 1.4em;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 12px;
  font-family: "Roboto", sans-serif;
  padding-bottom: 0.8rem;
}
.heading2 h2 {
  color: #ffffff;
  font-size: 48px;
  font-weight: 800;
  line-height: 1.2em;
  font-family: "Montserrat", sans-serif;
  padding-top: 0.8rem;
  padding-bottom: 0.5rem;
  margin-bottom: 20px;
}
#btn {
  font-size: 14px;
  font-weight: 600;
  letter-spacing: 0px;
  border: 1px solid #ffffff;
  color: #ffffff;
  background-color: rgba(0, 0, 0, 0);
  padding: 15px 60px 15px 60px;
  transition: color 0.3s, border-color 0.3s, transform 0.3s; /* Added transform to transition */
}

#btn:hover {
  color: red;
  border-color: red;
  transform: scale(1.1); /* Grow size by 10% on hover */
  animation: bounce 0.3s infinite alternate; /* Applying bouncing animation */
}

@keyframes bounce {
  0% {
    transform: scale(1); /* Original size */
  }
  100% {
    transform: scale(1.05); /* Slightly bigger size */
  }
}

.video {
  position: relative;

  width: 100%;

  text-align: center;
}
.video img {
  width: 100%;
  max-width: 400px;
}
.playIcon {
  position: absolute;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);

  color: #fff; /* Adjust color and opacity as needed */
  font-size: 170px;
  filter: drop-shadow(1px 0 6px rgba(0, 0, 0, 0.3));
}

@media (max-width: 1020px) {
  .heading1 h1 {
    font-size: 0.9em;
    line-height: 1.7em;
  }
  .heading2 h2 {
    font-size: 27px;
  }
  .video {
    padding: 75px;
  }
}
@media (max-width: 767px) {
  .imageSection {
    height: 750px;
  }
  .maincontent {
    display: block;
    height: 750px;
  }
  .heading1 {
    padding-top: 1rem;
  }
  .content {
    max-width: 100%;
  }
  .video {
    max-width: 100%;
  }
}
@media (max-width: 350px) {
  .video {
    padding: 40px;
  }
}

/* ///////////////////////////////body details section //////////////////// */
.ExtendedTestBodyDetails {
  max-width: 1000px;
  margin-left: auto;
  margin-right: auto;
  font-family: "Roboto", sans-serif;
  text-align: center;
  padding: 6rem 0;
}
.ExtendedTestBodyDetails a {
  text-decoration: none;
  color: #eb0009;
}
.ExtendedTestBodyDetails h2 {
  color: #000000;
  font-size: 2.7em;
  margin-bottom: 20px;
  font-weight: 600;
}
.ExtendedTestBodyDetails p {
  text-align: center;
  color: #000000;
  font-size: 16px;
  font-weight: 300;
  margin-bottom: 20px;
  line-height: 28px;
}
