/* /////////////////////////why choose us css/////////// */
.features {
  padding: 2rem 0;
}
.features h4 {
  color: #000000;
  font-size: 65px;
  font-weight: 700;
  line-height: 1.2em;
  text-align: center;
  font-family: "Roboto", sans-serif;
  margin-bottom: 20px;
}
.features p {
  color: #7a7a7a;
  line-height: 28px;
  text-align: center;
  font-weight: 400;
  font-family: "Montserrat", sans-serif;
}
.mainFeatures {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(250px, 1fr));
  gap: 20px;
  font-family: "Montserrat", sans-serif;
  text-align: center;
  max-width: 1140px;
  padding-left: 15px;
  padding-right: 15px;
  padding-top: 2rem;
  margin-left: auto;
  margin-right: auto;
  width: 100%;
}
.column {
  padding: 25px 25px 55px 25px;
  background-color: #ffffff;

  box-shadow: 0px 0px 55px 5px rgba(0, 0, 0, 0.06);

  transition: box-shadow 0.3s ease;
}

.column:hover {
  box-shadow: 0px 0px 55px 5px rgba(0, 0, 0, 0.203);
  border: 1px solid #eb0009;
}
.column span {
  font-size: 50px;
  color: #706c6c;
  display: inline-block;
  padding: 30px;
  margin-right: auto;
  margin-left: auto;
}
.column h3 {
  font-size: 26px;
  line-height: 1.2;
  font-weight: 700;
  margin-bottom: 10px;
  color: #000000;
}
.column p {
  font-size: 16px;
  font-family: "Montserrat", sans-serif;
  font-weight: 300;
  line-height: 1.7em;
  color: #7a7a7a;
}
#featuresIcon {
  transition: transform 0.3s ease;
}
#featuresIcon:hover {
  transform: scale(1.2);
  color: #eb0009;
}
#featuresIconSRU {
  font-size: 6rem;
}
@media (max-width: 1085px) {
  .features h4 {
    font-size: 45px;
  }
}
@media (max-width: 767px) {
  .features h4 {
    font-size: 30px;
  }
}
/* ///////////////////////////ENquiry Form ///////////////// */
.formContainer {
  padding: 2rem 0;
}
.formContainer hr {
  border: 2px solid #eb0009;
  opacity: 1;
}
.innerFormSection {
  max-width: 600px;
  margin-left: auto;
  margin-right: auto;
  background: linear-gradient(135deg, #6f00ab, #e3aaff);
  border-radius: 10px;
  box-shadow: 0 0 10px #ccc;
}
.enquiryForm {
  padding: 2rem;
}
.enquiryForm h4 {
  text-align: center;
  font-family: "Antonio", sans-serif;
  color: white;
  font-size: 48px;
  font-weight: 600;
}

.formGroup {
  display: flex;
  flex-direction: column;
  margin: 1rem 0px;
}

.formGroup input {
  display: block;
  width: 100%;
  padding: 0.375rem 0.75rem;
  font-size: 1rem;
  line-height: 1.5;
  color: #495057;
  background-color: #fff;
  background-clip: padding-box;
  border: 1px solid #ced4da;
  border-radius: 0.25rem;
  -webkit-transition: 0.5s;
  transition: 0.5s;
  outline: none;
  font-family: "Antonio", sans-serif;
}
.formGroup input:focus {
  border: 1px solid #eb0009;
}
.formGroup textarea {
  display: block;
  width: 100%;
  padding: 0.375rem 0.75rem;
  font-size: 1rem;
  line-height: 1.5;
  color: #495057;
  background-color: #fff;
  background-clip: padding-box;
  border: 1px solid #ced4da;
  border-radius: 0.25rem;
  -webkit-transition: 0.5s;
  transition: 0.5s;
  outline: none;
  font-family: "Antonio", sans-serif;
}
.formGroup textarea:focus {
  border: 1px solid #eb0009;
}
.formBtn {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 100%;
  margin-top: 2rem;
}
#formBtn {
  padding: 15px 75px 15px 75px;
  margin: 0px 1rem;
  border-radius: 10px;
  width: 100%;
  background-color: #eb0009;
  border: none;
  color: #fff;
  font-size: 14px;
  font-weight: 600;
  text-transform: uppercase;
  font-family: "Antonio", sans-serif;
}
#formBtn:hover {
  border: 1px solid red;
  background-color: #fff;
  color: red;
}

@media (max-width: 1024px) {
  .formContainer {
    padding: 100px 150px 100px 150px;
  }
  .innerFormSection {
    max-width: 1024px;
  }
  .enquiryForm {
    padding: 75px 75px 75px 75px;
  }
}
@media (max-width: 767px) {
  .formContainer {
    padding: 100px 75px 100px 75px;
  }
  .innerFormSection {
    max-width: 767px;
  }
  .enquiryForm h4 {
    font-size: 45px;
  }
  .enquiryForm {
    padding: 50px 50px 50px 50px;
  }
}
@media (max-width: 524px) {
  .formContainer {
    padding: 50px 30px 50px 30px;
  }
  .enquiryForm h4 {
    font-size: 30px;
  }
  .innerFormSection {
    max-width: 524px;
  }
  .enquiryForm {
    padding: 30px 30px 30px 30px;
  }
}
